def main():
    import sys
    import heapq

    def dijkstra(graph, start, end, k):
        n = len(graph)
        dist = [[float('inf')] * (k + 1) for _ in range(n)]
        dist[start][0] = 0
        pq = [(0, 0, start)]

        while pq:
            current_cost, current_day, current_city = heapq.heappop(pq)

            if current_city == end and current_day >= k:
                return current_cost

            for next_day, next_city, cost in graph[current_city]:
                if next_day >= current_day:
                    new_cost = current_cost + cost
                    if new_cost < dist[next_city][next_day - current_day]:
                        dist[next_city][next_day - current_day] = new_cost
                        heapq.heappush(pq, (new_cost, next_day, next_city))

        return float('inf')

    def solve():
        import sys
        import heapq

        n, m, k = map(int, sys.stdin.readline().split())
        flights = [list(map(int, sys.stdin.readline().split())) for _ in range(m)]

        graph = [[] for _ in range(n + 1)]
        reverse_graph = [[] for _ in range(n + 1)]

        for d, f, t, c in flights:
            if f == 0:
                graph[t].append((d, 0, c))
                reverse_graph[0].append((d, t, c))
            elif t == 0:
                graph[f].append((d, 0, c))
                reverse_graph[0].append((d, f, c))
            else:
                graph[f].append((d, t, c))
                reverse_graph[t].append((d, f, c))

        min_cost = float('inf')
        for i in range(1, n + 1):
