            cost_from_metropolis = dijkstra(reverse_graph, 0, i, k)
            if cost_to_metropolis != float('inf') and cost_from_metropolis != float('inf'):
                min_cost = min(min_cost, cost_to_metropolis + cost_from_metropolis)

        if min_cost == float('inf'):
